from copy import deepcopy
from typing import Dict, Any, List

import boto3

from service.logs import Log, LogEventType

DYNAMODB_RESOURCE = boto3.resource("dynamodb")
DYNAMODB_TABLE = DYNAMODB_RESOURCE.Table("TodoAppTable")


class DynamoDBQueryRequest:

    def __init__(
        self,
        key_condition_expression,
        filter_expression=None,
        projection_expression: str = None,
        expression_attribute_names: dict = None,
        limit: int = None,
        index_name: str = None,
        scan_index_forward: bool = None,
        exclusive_start_key: dict = None,
    ):
        self.key_condition_expression = key_condition_expression
        self.filter_expression = filter_expression
        self.projection_expression = projection_expression
        self.expression_attribute_names = expression_attribute_names
        self.limit = limit
        self.index_name = index_name
        self.scan_index_forward = scan_index_forward
        self.exclusive_start_key = exclusive_start_key

    def to_dict(self):
        request = {
            "KeyConditionExpression": self.key_condition_expression,
            "ProjectionExpression": self.projection_expression,
            "ExpressionAttributeNames": self.expression_attribute_names,
            "FilterExpression": self.filter_expression,
            "Limit": self.limit,
            "ScanIndexForward": self.scan_index_forward,
            "ExclusiveStartKey": self.exclusive_start_key,
        }
        return {k: v for k, v in request.items() if v is not None}

    def readable_condition_expression(self):
        return str(self.key_condition_expression.get_expression())


class DynamoDBQueryResponse:

    def __init__(self, items: List[Dict], last_evaluated_key: dict):
        self.items = items
        self.last_evaluated_key = last_evaluated_key


class DynamoDBService:

    def __init__(self):
        self.dynamodb_resource = DYNAMODB_RESOURCE
        self.table = DYNAMODB_TABLE

    def query(
        self, dynamodb_query_request: DynamoDBQueryRequest
    ) -> DynamoDBQueryResponse:
        try:
            request_as_dict = dynamodb_query_request.to_dict()
            log_message = deepcopy(request_as_dict)
            log_message["readable_condition_expression"] = (
                dynamodb_query_request.readable_condition_expression()
            )
            Log(data=log_message, event_type=LogEventType.DynamoDBQuery).info()
            response = self.table.query(**request_as_dict)
            return DynamoDBQueryResponse(
                items=response.get("Items", []),
                last_evaluated_key=response.get("LastEvaluatedKey"),
            )
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()

    def put_item(self, item: Dict[str, Any]):
        try:
            Log(data=item, event_type=LogEventType.DynamoDBPutItem).info()
            self.table.put_item(Item=item)
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()

    def update_item(
        self,
        key: Dict[str, Any],
        updates: Dict[str, Any],
        item_entity_class_instance: Any,
    ):
        try:
            updates.pop("pk", None)
            updates.pop("sk", None)

            for update_key in updates.keys():
                if not hasattr(item_entity_class_instance, update_key):
                    raise ValueError(
                        f"Key '{update_key}' is not an attribute of {self.__class__.__name__}"
                    )

            update_expression = "set " + ", ".join(f"{k}=:{k}" for k in updates.keys())
            expression_attribute_values = {f":{k}": v for k, v in updates.items()}

            Log(
                data={
                    "key": key,
                    "update_expression": update_expression,
                    "expression_attribute_values": expression_attribute_values,
                },
                event_type=LogEventType.DynamoDBUpdateItem,
            ).info()
            self.table.update_item(
                Key=key,
                UpdateExpression=update_expression,
                ExpressionAttributeValues=expression_attribute_values,
                ReturnValues="UPDATED_NEW",
            )
        except Exception as e:
            Log(data=str(e), event_type=LogEventType.DynamoDBException).exception()
